273	    private boolean isSameIdentity(Owner existing, Owner candidate) {
274	        return Objects.equals(normalizeName(existing.getLastName()), normalizeName(candidate.getLastName()))
275	            && Objects.equals(existing.getTelephone(), candidate.getTelephone());
276	    }
