278	    /**
279	     * Normalises a name for duplicate detection so that comparisons ignore letter
280	     * case as well as surrounding and repeated whitespace. For example
281	     * {@code "  john   smith "} and {@code "John Smith"} normalise to the same value.
282	     *
283	     * @param name the raw name value (may be {@code null})
284	     * @return the normalised name, or {@code null} if {@code name} is {@code null}
285	     */
286	    private String normalizeName(String name) {
287	        if (name == null) {
288	            return null;
289	        }
290	        return name.trim().replaceAll("\\s+", " ").toLowerCase();
291	    }
